%[text] # One Charged Plate and a Point Particle
clear;
% The variables
% a : angle of point in plate
% d : distance from plate to particle
% v : relative particle velocity [0...1]
% v_a: change in velocity due to aceleration v_a = a*Dt = a*R/C
% r : radial distance between axis to point in plate
syms a d v v_a r real positive;
assume(d>0)
assume(r>=0)
assume(v>=0)
assumeAlso (v < 1)
assume(a>=0)
taylorOrder = 5;

% Particle velocity
vp = [v,0,0];
%%
%[text] ## The vectors
%[text] d= distance from the charge to the plate
%[text] r = radius of a circle in the plate
%[text] The speed of light is 1 (c=1)
%[text] 
R = (d^2+r^2)^(1/2) % total distance from a point in the plate to the charge %[output:0c987dd1]

% Get two points per circle. 
% a is the angle
vec_l1 = [d,r*cos(a),r*sin(a)]/R  % velocity vector of light from a point 1 in left positive plate at angle a %[output:7595b9fe]

vec_l2 = [d,-r*cos(a),-r*sin(a)]/R  % velocity vector of light from a point 2 in left positive plate at 180+a %[output:6ebffa30]
r_vec_l1 = (vec_l1 - vp) % left plate relative velocity of 1 particle (v in light speed fraction =v/c) %[output:269a14cd]
r_vec_l2 = (vec_l2 - vp) % left plate relative velocity of 2 particle (v in light speed fraction =v/c) %[output:273c8f2d]

%%
%[text] ## The Anomality 
% 1 particle disparity between photon angle and trayectory
Fz_1 = simplify(simplifyFraction(dot(r_vec_l1,r_vec_l1)/dot(vec_l1,r_vec_l1))) %  left plate %[output:60c8e5e3]


% 2 particle disparity between photon angle and trayectory
Fz_2 = simplify(simplifyFraction(dot(r_vec_l2,r_vec_l2)/dot(vec_l2,r_vec_l2))) %  left plate %[output:625efe55]


%%
%[text] ## The Relative Net Force of the Two Points
% Force of the two point in plate and moving particle
dforce = ((Fz_1/R^2)*vec_l1 + (Fz_2/R^2)*vec_l2)/2; % net Force in the x direction first points.
dforce = simplify(expand(dforce),'Steps',100) % Two charges %[output:6ce5a923]
dforce_x = dforce(1) %[output:1896dc1f]
%dforce_x = simplify(taylor(expand(subs(dforce_x/2,v,v+v_a) + dforce_x/2),v_a,order=2))
%%
%[text] ## Check at v = 0, r =0
df_v_zero = simplify(subs(dforce_x,[v,r],[0,0]),'Steps',100) % Due to the two point charges %[output:4e17f5bd]
df_v_one = simplify(subs(dforce_x,[v,r],[v,0]),'Steps',100) % Due to the two point charges %[output:067ec3c4]
%%
%[text] ## Integrate all the angles
%dforce_xT = expand(taylor(dforce_x,v,Order=taylorOrder));
dforce_xT = dforce_x;

dcircle = int(dforce_xT,a,0,pi); % From zero to pi i.e., the full circle
%%
dcircle = simplify(dcircle,steps=100); % Net force of the two full circles with charge density
df_v_zero = simplify(subs(dcircle,[v,r],[v,0]),'Steps',100) % Net force of the full zero radius circle (point) %[output:0ad432d7]
%[text] ## 
%%
%[text] ## Integrate for all values of r
syms R_o real
assumeAlso (R_o>0)
dtotf = r*dcircle/pi  %[output:13ac1d5a]
dtotf = simplify(expand(taylor(dtotf,v,Order=taylorOrder))); % Taylor
%dtotf = simplify(subs(dtotf,v,0)) %static
totInt = int(dtotf,r,0,R_o); % Add all the circles
%%
totf = simplify(totInt,'Criterion','preferReal','Steps',100) % The force on a charge due a charge surface density %[output:51de6feb]

%%
%[text] ## Set the Plates Radius to Infinity
sympref('PolynomialDisplayStyle', 'ascend');
totfInf = simplify(limit(totf,R_o,Inf)) % Net force by plate charge density %[output:0edfd1ec]
%totfInf = subs(totfInf,v,-v)

%%
figure(1)
plotrange = [0,0.99];
fplot(totfInf,plotrange) %[output:5c98c7ae]
hold on %[output:5c98c7ae]
relEq = sqrt(1-v^2) %[output:7877f402]
relEqApx = taylor(relEq,v,Order=taylorOrder) %[output:96daa54e]
fplot(relEq,plotrange) %[output:5c98c7ae]
fplot(relEqApx,plotrange) %[output:5c98c7ae]
xlabel('v/c')  %[output:5c98c7ae]
ylabel('ratio')  %[output:5c98c7ae]
legend({'Force Carriers',"Lorentz Mass","Lorentz Apx"},'Location','northeast') %[output:5c98c7ae]
hold off %[output:5c98c7ae]



%[text] ## Set the Plates Radius to 0.1\*d
totf_d = simplify(limit(totf,R_o,0.1*d)) % Net force by plate charge density %[output:967738ee]
totf_dV0 = subs(totf_d,v=0) %[output:3fe28da3]

totf_dRel = simplify(totf_d/totf_dV0) %[output:00bc2d08]
totf_dRel0 = subs(totf_dRel,v_a,0) %[output:03a0f4bc]

%%
%[text] ## Plots
figure(1)
plotrange = [0,0.99];
fplot(totfInf,plotrange) %[output:272b2cf9]
hold on %[output:272b2cf9]
relEq = sqrt(1-v^2) %[output:8f7a2c1a]
relEqApx = taylor(relEq,v,Order=taylorOrder) %[output:5f2426ba]
fplot(relEq,plotrange) %[output:272b2cf9]
fplot(relEqApx,plotrange) %[output:272b2cf9]
fplot(totf_dRel0,plotrange) %[output:272b2cf9]
xlabel('v/c')  %[output:272b2cf9]
ylabel('ratio')  %[output:272b2cf9]
legend({'Force Carriers',"Lorentz Mass","Lorentz Apx","Fd"},'Location','northeast') %[output:272b2cf9]
hold off %[output:272b2cf9]
%[text] ## 
%%
%[text] ## 

